-- Node: sync-elderly (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Elderly Syncope","body":"**Particularly challenging** — many present with unexplained falls rather than syncope. [37,38]\n\n**Key points:**\n• 25-50% of unexplained falls in elderly may be syncope-related [37,39]\n• Almost half of elderly with dementia referred for unexplained falls receive a syncope diagnosis [39]\n• Neurally mediated syncope is still common in this age group [37]\n• QTc prolongation occurs in 25% of elderly — QTc >500 ms predicts 30-day and 1-year mortality [40,41]\n\n**Hospitalization controversy:**\n• Older adults often have multiple risk factors and worse outcomes overall\n• However, for unexplained syncope WITHOUT a serious ED diagnosis, **hospitalization does not improve 30-day adverse outcomes** [42]\n• Age >65 alone and unexplained syncope are NOT independent predictors of mortality [43,44]\n• Mortality is related primarily to **underlying comorbidities**, not the syncope itself [42,45]\n\nHospitalization may increase likelihood of identifying a serious diagnosis, but does not appear to improve mortality.","citation":[37,38,39,40,41,42,43,44],"summary":"25-50% of elderly falls may be syncope — hospitalization does not improve 30-day outcomes; mortality from comorbidities","skippable":true}'::jsonb
WHERE id = 'sync-elderly' AND tree_id = 'syncope';

-- Node: sync-disposition-intermediate (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Intermediate Risk — Observation vs. Outpatient","body":"**Shared decision-making recommended.** [1,2]\n\n**Intermediate-risk factors:** [1]\n• Age ≥50 years\n• Prior history of cardiac disease\n• Cardiac device without dysfunction\n• Family history of early sudden cardiac death\n• Symptoms not consistent with reflex-mediated syncope\n\n**Key point:** Patients with risk factors by PMH (CAD, HF) but with a **benign cause identified in the ED** (e.g., dehydration) may be discharged safely. [46]\n\n**If observation/discharge:**\n• Structured ED observation protocol may reduce admissions [47]\n• Ensure close follow-up (PCP, cardiology)\n• Consider referral for:\n  - Ambulatory ECG monitoring (Holter, event monitor)\n  - Tilt-table testing\n  - Implantable loop recorder\n  - Electrophysiology evaluation [1]\n\n**If admitted:**\n• Telemetry monitoring\n• Targeted workup based on risk profile","citation":[1,2,45,46],"recommendation":"Shared decision-making. Consider ED observation protocol. If discharge: close follow-up + ambulatory monitoring referral.","confidence":"recommended"}'::jsonb
