-- Node: sync-disposition-low (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Low Risk — Discharge","body":"**Low-risk patients should generally be discharged**, even with unexplained syncope. [1,2]\n\n**Low-risk features (ESC):** [2]\n• Young age with typical features of reflex syncope\n• No history of cardiac disease\n• Syncope only when standing\n• Identifiable trigger (pain, blood, prolonged standing)\n• Normal ECG\n• Normal vital signs\n\n**Discharge counseling:**\n• Explain diagnosis and expected benign prognosis\n• Counsel on avoidance of known triggers\n• Counterpressure maneuvers (leg crossing, hand gripping) for prodromal symptoms\n• Adequate hydration and salt intake\n• Review fall risk and injury prevention\n\n**Recurrence:** ~9% recurrence within 6 months; 3+ lifetime episodes most predictive of future recurrence [48]\n\n**Driving:** Be familiar with state laws regarding driving after syncope. Consider referral before return to work for commercial drivers or high-risk occupations. [49]\n\n**Follow-up:** PCP for recurrent or unexplained syncope.\n\n[Discharge Instructions](#/info/syncope-discharge) — shareable patient handout","citation":[1,2,47,48],"recommendation":"Discharge with reassurance, trigger avoidance counseling, and PCP follow-up. Address driving restrictions if applicable. Review [Discharge Instructions](#/info/syncope-discharge) with patient.","confidence":"definitive"}'::jsonb
WHERE id = 'sync-disposition-low' AND tree_id = 'syncope';

-- Node: sync-no-head-ct (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Head CT Is NOT Indicated","body":"**ACEP \"Choosing Wisely\" recommendation:** Avoid head CT in asymptomatic patients with syncope, minimal trauma, and a normal neurologic examination. [16]\n\n**Evidence:**\n• Head CT has very low yield (<0.1%) in determining the cause of syncope [50]\n• Commonly ordered despite lack of utility — one study found 58% of pediatric syncope patients received head CT [36]\n• No neurological symptoms + no head trauma + normal neuro exam = **no head CT needed** [16,50]\n\n**Only obtain head CT if:**\n• Significant head trauma from the fall\n• Neurological deficit on examination\n• Suspicion for SAH (thunderclap headache)","citation":[16,36,49],"summary":"ACEP Choosing Wisely: no head CT without neuro deficit or head trauma — <0.1% yield for syncope cause","skippable":true}'::jsonb
WHERE id = 'sync-no-head-ct' AND tree_id = 'syncope';

