UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Pulmonary Embolism & Syncope","body":"**PE is uncommon among syncope patients.** [51,52]\n\nExisting clinical decision rules (PERC) adequately identify syncope patients with PE. [51]\n\n**Routine D-dimer is NOT indicated** in syncope patients without independent indications for PE evaluation. [53,54]\n\n**When to consider PE:**\n• Unexplained persistent tachycardia, hypotension, tachypnea, or hypoxia in ED\n• Recent surgery, immobilization, or other VTE risk factors\n• Syncope + dyspnea + pleuritic chest pain\n\n**Apply standard PE rules** (PERC → Wells → CTPA) only when clinically indicated — do NOT screen all syncope patients for PE.","citation":[50,51,52,53],"summary":"Routine D-dimer NOT indicated — PE uncommon in syncope; apply standard PERC/Wells only when clinically suspected","skippable":true}'::jsonb
